// Lee el inventario (CSV separado por ;) y se queda con los documentos del rango pedido.
const f = $('Indexar una tanda del corpus').first().json;
const desde = Number(f.desde) || 1;
const hasta = Number(f.hasta) || desde;
const texto = String($input.first().json.csv ?? '');

const parsear = (linea) => {
  const campos = [];
  let actual = '';
  let entreComillas = false;
  for (let i = 0; i < linea.length; i++) {
    const c = linea[i];
    if (entreComillas) {
      if (c === '"' && linea[i + 1] === '"') { actual += '"'; i++; }
      else if (c === '"') entreComillas = false;
      else actual += c;
    } else if (c === '"') entreComillas = true;
    else if (c === ';') { campos.push(actual); actual = ''; }
    else actual += c;
  }
  campos.push(actual);
  return campos;
};

const lineas = texto.split(/\r?\n/).filter((l) => l.trim());
const cabecera = parsear(lineas.shift()).map((k) => k.trim().replace(/^﻿/, ''));
const base = 'https://raw.githubusercontent.com/Lougedo/rag_nexora_salud/main/nexora_salud_corpus/';

const docs = lineas
  .map((l) => {
    const v = parsear(l);
    return Object.fromEntries(cabecera.map((k, i) => [k, (v[i] ?? '').trim()]));
  })
  .filter((d) => Number(d.id) >= desde && Number(d.id) <= hasta)
  .map((d) => ({ json: {
    id: d.id,
    fichero: d.filename,
    titulo: d.titulo,
    capa: d.capa,
    categoria: d.categoria,
    fuente: d.fuente,
    url: base + encodeURIComponent(d.filename),
  } }));

if (!docs.length) throw new Error(`No hay documentos entre ${desde} y ${hasta}`);
return docs;

// Resumen de la tanda: documentos, trozos guardados y errores.
const docs = $('Documentos de la tanda').all().map((i) => i.json);
const filas = $input.all().map((i, n) => ({ ...docs[n], ...i.json }));
const trozos = filas.reduce((s, f) => s + (Number(f.trozos) || 0), 0);
const errores = filas
  .filter((f) => f.error || !f.trozos)
  .map((f) => `${f.id} · ${f.titulo}: ${typeof f.error === 'object' ? (f.error.message ?? JSON.stringify(f.error)) : (f.error || 'sin trozos')}`);

return [{ json: {
  documentos: filas.length,
  trozos,
  con_error: errores.length,
  errores,
  detalle: filas.map((f) => `${f.id} · ${f.trozos ?? 0} trozos`),
} }];
